mapper.select:
SELECT * FROM agent_conversations
WHERE organization_id = #{organizationId}
  AND agent_id = #{agentId}
  AND archived_at IS NULL
ORDER BY last_message_at DESC, created_at DESC, id DESC

mapper.update:
UPDATE agent_conversations
SET last_message_at = now(), updated_at = now()
WHERE id = #{id}

mapper.select:
SELECT * FROM (
  SELECT * FROM agent_messages
  WHERE organization_id = #{organizationId} AND conversation_id = #{conversationId}
  ORDER BY created_at DESC, id DESC
  LIMIT #{limit}
) recent
ORDER BY created_at ASC, id ASC

SELECT * FROM (
  SELECT * FROM agent_messages
  WHERE organization_id = #{organizationId}
    AND conversation_id = #{conversationId}
    AND id <> #{excludeId}
    AND status IN ('done', 'failed')
  ORDER BY created_at DESC, id DESC
  LIMIT #{limit}
) recent
ORDER BY created_at ASC, id ASC

mapper.update:
UPDATE agent_messages
SET lease_expires_at = #{leaseExpiresAt}
WHERE id = #{messageId}
  AND agent_id = #{agentId}
  AND role = 'user'
  AND status = 'processing'
  AND lease_id = #{leaseId}
  AND lease_expires_at > now()

mapper.select:
SELECT EXISTS (
  SELECT 1 FROM agent_messages
  WHERE id = #{messageId}
    AND agent_id = #{agentId}
    AND role = 'user'
    AND status = 'processing'
    AND lease_id = #{leaseId}
    AND lease_expires_at > now()
)

mapper.update:
UPDATE agent_messages
SET status = 'queued', error_summary = NULL, lease_id = NULL, lease_expires_at = NULL
WHERE agent_id = #{agentId}
  AND id = #{id}
  AND role = 'user'
  AND status = 'processing'
  AND lease_id = #{leaseId}

UPDATE agent_messages
SET status = #{status}, error_summary = #{errorSummary}
WHERE id = #{id}

mapper.select:
SELECT EXISTS (
  SELECT 1 FROM agent_messages WHERE agent_id = #{agentId} AND status = 'processing'
)

SELECT EXISTS (
  SELECT 1 FROM agent_messages WHERE agent_id = #{agentId} AND role = 'user' AND status = 'queued'
)

SELECT * FROM agent_messages
WHERE agent_id = #{agentId}
  AND role = 'user'
  AND created_at > #{since}
ORDER BY created_at ASC, id ASC
LIMIT #{limit}
